import sys
from collections import deque

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    a = list(map(int, input[1:]))

    def bfs(start):
        queue = deque([(start, 0)])
        visited = [False] * n
        visited[start] = True
        while queue:
            pos, dist = queue.popleft()
            if a[pos] % 2 != a[start] % 2:
                return dist
            for next_pos in [pos - a[pos], pos + a[pos]]:
                if 0 <= next_pos < n and not visited[next_pos]:
                    visited[next_pos] = True
                    queue.append((next_pos, dist + 1))
        return -1

    result = []
    for i in range(n):
        result.append(bfs(i))

    print(" ".join(map(str, result)))

if __name__ == "__main__":
    main()
